from routekit.shortest_path import shortest_path


def plan_drop_route(adj: Mapping[str, Mapping[str, int]], origin: str, destination: str, drops: Sequence[str]) -> Optional[Tuple[int, List[str]]]:
    if len(drops) != len(set(drops)):
        raise ValueError("drops contains duplicates")
    if len(drops) > 6:
        raise ValueError("drops contains more than 6 depots")
    for node in [origin, destination] + list(drops):
        if node not in adj:
            raise KeyError(node)
    if not drops:
        return shortest_path(adj, origin, destination)
    best = None
    for drop_order in permutations(drops):
        waypoints = [origin] + list(drop_order) + [destination]
        total_km = 0
        full_path = []
        legs = 0
        valid = True
        for i in range(len(waypoints) - 1):
            segment = shortest_path(adj, waypoints[i], waypoints[i + 1])
            if segment is None:
                valid = False
                break
            seg_km, seg_path = segment
            total_km += seg_km
            legs += len(seg_path) - 1
            if i == 0:
                full_path = list(seg_path)
            else:
                full_path.extend(seg_path[1:])
        if not valid:
            continue
        candidate = (total_km, legs, drop_order, full_path)
        if best is None:
            best = candidate
        else:
            if (total_km, legs, drop_order) < (best[0], best[1], best[2]):
                best = candidate
    if best is None:
        return None
    return (best[0], best[3])
